create view registros_legajo as
select u.id as usuario_id, u.legajo as legajo, a.id as asignatura_id, ac.nombre as carrera, m.nombre as materia, r.id as registro_id, r.entrada as registro_entrada, r.salida as registro_salida, r.obs as registro_obs from usuarios u join cargos c on u.id=c.usuario_id join asignaturas a on a.id=c.asignatura_id join asignaturas_materias m on a.materia_id=m.id join asignaturas_carreras ac on a.carrera_id=ac.id join horarios h on c.asignatura_id=h.asignatura_id LEFT join registros r on r.asignatura_id=c.asignatura_id and r.usuario_id=u.id and date(r.fecha)=curdate() where WEEKDAY(NOW())+1 = h.dia;
